// Problem: Design a parking lot system with multiple floors and spot types

// Noun: Vehicle -> has type, license plate, can enter/exit
record Vehicle(String licensePlate, VehicleType type) {}

// Noun: Parking Spot -> has location, availability, can be reserved
class ParkingSpot {
    private final String spotId;
    private final SpotType type;
    private boolean isOccupied;

    public boolean reserve(Vehicle vehicle) {
        if (!isOccupied) {
            this.isOccupied = true;
            return true;
        }
        return false;
    }
}

// Noun: Ticket -> has entry time, vehicle info, represents a parking session
record Ticket(String ticketId, Vehicle vehicle, LocalDateTime entryTime) {}

// Noun: Parking Floor -> has multiple spots, manages spot allocation
class ParkingFloor {
    private final int floorNumber;
    private final List<ParkingSpot> spots;

    public Optional<ParkingSpot> findAvailableSpot(VehicleType type) {
        return spots.stream()
            .filter(spot -> !spot.isOccupied() && spot.canFit(type))
            .findFirst();
    }
}

// WRONG: God class with too many responsibilities
class ParkingLot {
    private List<ParkingSpot> spots;

    public Ticket parkVehicle(Vehicle vehicle) { /* finds spot, creates ticket, calculates fee */ }
    public double calculateFee(Ticket ticket) { /* fee logic here */ }
    public void generateReport() { /* reporting logic */ }
}

// RIGHT: Each class has one responsibility
class ParkingSpot {
    private boolean isOccupied;

    public boolean reserve() {  // Only manages spot state
        if (!isOccupied) {
            isOccupied = true;
            return true;
        }
        return false;
    }
}

class FeeCalculator {
    public double calculate(Ticket ticket, LocalDateTime exitTime) {  // Only calculates fees
        var duration = Duration.between(ticket.entryTime(), exitTime);
        return duration.toHours() * getRateFor(ticket.vehicle().type());
    }
}

class TicketGenerator {
    public Ticket generate(Vehicle vehicle, ParkingSpot spot) {  // Only creates tickets
        return new Ticket(UUID.randomUUID().toString(), vehicle, LocalDateTime.now(), spot);
    }
}

