// Basic enum with constants
enum TicketStatus {
    ACTIVE, PAID, EXPIRED, LOST
}

// Enum with fields, constructor, and methods
enum VehicleType {
    MOTORCYCLE(1, 10.0),
    CAR(2, 20.0),
    TRUCK(4, 40.0);

    private final int spotsRequired;  // How many spots this vehicle needs
    private final double baseRate;    // Hourly parking rate

    VehicleType(int spotsRequired, double baseRate) {
        this.spotsRequired = spotsRequired;
        this.baseRate = baseRate;
    }

    public boolean canFitIn(SpotType spotType) {  // Business logic in enum
        return spotType == SpotType.LARGE || 
               (this == MOTORCYCLE && spotType == SpotType.COMPACT);
    }

    public double calculateFee(long hours) {
        return hours * baseRate;
    }
}

enum SpotType {
