// One-to-many: ParkingLot has many ParkingFloors
class ParkingLot {
    private final String lotId;
    private final List<ParkingFloor> floors;  // Collection field

    public ParkingLot(String lotId) {
        this.lotId = lotId;
        this.floors = new ArrayList<>();  // Initialize the collection
    }

    public void addFloor(ParkingFloor floor) {  // Controlled addition
        floors.add(floor);
    }

    public Optional<ParkingSpot> findAvailableSpot(VehicleType type) {  // Query the collection
        return floors.stream()
            .map(floor -> floor.findSpotForVehicle(type))
            .filter(Optional::isPresent)
            .map(Optional::get)
            .findFirst();
    }

    public List<ParkingFloor> getFloors() {  // Return unmodifiable view
        return List.copyOf(floors);  // Defensive copy to prevent external modification
    }
}

// One-to-many: ParkingFloor has many ParkingSpots
class ParkingFloor {
    private final int floorNumber;
    private final List<ParkingSpot> spots;

    public ParkingFloor(int floorNumber, List<ParkingSpot> spots) {
        this.floorNumber = floorNumber;
        this.spots = new ArrayList<>(spots);  // Copy to own the collection
    }
}
